{
  "status": "NEED_INFO",
  "summary": "Yêu cầu xây dựng một trang web bán hàng hoàn chỉnh với giao diện đẹp và đầy đủ chức năng. Sinh viên có quyền tự do lựa chọn công nghệ, hình thức làm việc (cá nhân hoặc nhóm) và sẽ được chấm điểm dựa trên mức độ hoàn thiện của sản phẩm vào cuối kỳ.",
  "deadline": {
    "value": null,
    "quote": "Nộp vào cuối kỳ"
  },
  "requirements": [
    {
      "content": "Thiết kế giao diện trang web bán hàng có tính thẩm mỹ.",
      "quote": "Làm một trang web bán hàng cho đẹp"
    },
    {
      "content": "Phát triển đầy đủ các chức năng cần thiết của một trang e-commerce.",
      "quote": "có đầy đủ các chức năng cần thiết"
    }
  ],
  "constraints": [
    {
      "content": "Tự do lựa chọn công nghệ sử dụng.",
      "quote": "Dùng công nghệ nào cũng được miễn là phù hợp"
    },
    {
      "content": "Hình thức thực hiện linh hoạt (cá nhân hoặc nhóm).",
      "quote": "Làm nhóm hoặc cá nhân tùy ý"
    }
  ],
  "deliverables": [
    {
      "content": "Sản phẩm trang web hoàn thiện.",
      "quote": "điểm tùy theo mức độ hoàn thiện của sản phẩm"
    }
  ],
  "grading_criteria": [
    {
      "content": "Điểm số dựa trên mức độ hoàn thiện và chất lượng của sản phẩm.",
      "quote": "điểm tùy theo mức độ hoàn thiện của sản phẩm"
    }
  ],
  "missing_info": [
    "Hạn nộp cụ thể (ngày, giờ).",
    "Danh sách các chức năng bắt buộc (ví dụ: giỏ hàng, thanh toán, quản lý kho, đăng ký/đăng nhập).",
    "Số lượng thành viên tối đa nếu làm nhóm.",
    "Yêu cầu về tài liệu đi kèm (báo cáo, sơ đồ thiết kế, hướng dẫn cài đặt).",
    "Nền tảng nộp bài (GitHub, hệ thống của trường, hay nộp file nén)."
  ],
  "questions": [
    "Bạn dự định làm cá nhân hay nhóm? Nếu làm nhóm thì có bao nhiêu người?",
    "Bạn đã có dự định sử dụng ngôn ngữ hay framework nào chưa (ví dụ: React, Node.js, PHP, Java...)?",
    "Bạn có danh sách chức năng cụ thể nào mà giảng viên đã gợi ý trên lớp không?",
    "Ngày cụ thể của 'cuối kỳ' mà bạn phải nộp bài là ngày nào?"
  ],
  "ambiguities": [
    {
      "content": "Tiêu chí 'cho đẹp' rất cảm tính, khó định lượng.",
      "quote": "Làm một trang web bán hàng cho đẹp"
    },
    {
      "content": "Cụm từ 'chức năng cần thiết' không xác định rõ phạm vi (MVP hay đầy đủ tính năng nâng cao).",
      "quote": "có đầy đủ các chức năng cần thiết"
    },
    {
      "content": "Không rõ 'công nghệ phù hợp' dựa trên tiêu chí đánh giá nào.",
      "quote": "Dùng công nghệ nào cũng được miễn là phù hợp"
    }
  ],
  "contradictions": [],
  "invalid_data": [],
  "injection_flags": [],
  "refusal_reason": null,
  "plan": [
    {
      "step": 1,
      "task": "Xác nhận lại hạn nộp và liệt kê chi tiết các tính năng cần làm (giỏ hàng, quản lý sản phẩm, thanh toán...).",
      "due": "Tuần 1"
    },
    {
      "step": 2,
      "task": "Lựa chọn công nghệ (Tech stack) và thiết kế sơ đồ cơ sở dữ liệu.",
      "due": "Tuần 1"
    },
    {
      "step": 3,
      "task": "Thiết kế giao diện (UI/UX) cho các trang chính (Home, Product Detail, Cart).",
      "due": "Tuần 2"
    },
    {
      "step": 4,
      "task": "Lập trình Back-end (API, Database) và tích hợp các chức năng cốt lõi.",
      "due": "Tuần 3-5"
    },
    {
      "step": 5,
      "task": "Lập trình Front-end và kết nối với Back-end.",
      "due": "Tuần 6-8"
    },
    {
      "step": 6,
      "task": "Kiểm thử (Fix bug) và hoàn thiện các yêu cầu về thẩm mỹ.",
      "due": "Tuần 9"
    },
    {
      "step": 7,
      "task": "Chuẩn bị tài liệu báo cáo và đóng gói mã nguồn để nộp.",
      "due": "Tuần nộp bài"
    }
  ]
}
